import importlib.util
import os
import shlex
import subprocess
import sys
from pathlib import Path

BUILD_DRIVE = Path(__file__).resolve().parent / "build-drive.sh"

EXPORTED = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-hashes --no-emit-project
pyside6-essentials==6.4.2
    # via mediatagger
python-mpv==0.9.1
    # via mediatagger
shiboken6==6.4.2
    # via pyside6-essentials
"""


def fake_command(bin_dir, name, script):
    (bin_dir / name).write_text(f"#!/bin/sh\n{script}\n")
    (bin_dir / name).chmod(0o755)


def fake_build_env(tmp_path, record):
    """Fake uv, apt-ftparchive and python3.13 on PATH, a Pi-like apt root with one .deb, home under tmp_path."""
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    (tmp_path / "exported.txt").write_text(EXPORTED)
    record.mkdir()
    fake_command(bin_dir, "uv", f"""
if [ "$1" = export ]; then
  shift
  for a; do
    case "$a" in --frozen|--no-dev|--no-hashes|--no-emit-project) ;; *) exit 2;; esac
  done
  [ $# -eq 4 ] || exit 2
  cat "{tmp_path / 'exported.txt'}"
  exit 0
fi
i=1; while [ -e "{record}/$i" ]; do i=$((i+1)); done
mkdir "{record}/$i"
printf '%s\\0' "$@" > "{record}/$i/args"
prev=
for a; do
  case "$prev" in -r|--requirement|--requirements) cp "$a" "{record}/$i/requirements";; esac
  case "$a" in --requirement=*|--requirements=*) cp "${{a#*=}}" "{record}/$i/requirements";; esac
  prev=$a
done""")
    fake_command(bin_dir, "apt-ftparchive", "printf 'Package: libmpv2\\n'")
    fake_command(bin_dir, "python3.13", f'exec "{sys.executable}" "$@"')
    aptpi = tmp_path / "aptpi"
    archives = aptpi / "var" / "cache" / "apt" / "archives"
    archives.mkdir(parents=True)
    (archives / "libmpv2_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\ndeb")
    (tmp_path / "home").mkdir()
    return {
        **os.environ,
        "PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}",
        "HOME": str(tmp_path / "home"),
        "APTPI": str(aptpi),
    }


def uv_pip_install_calls(record):
    calls = []
    for call in sorted(record.iterdir(), key=lambda d: int(d.name)):
        args = [a.decode() for a in (call / "args").read_bytes().split(b"\0")[:-1]]
        if args[:2] != ["pip", "install"]:
            continue
        requirements = call / "requirements"
        calls.append({
            "args": args[2:],
            "requirements": requirements.read_text() if requirements.exists() else "",
        })
    return calls


def requirement_specs(text):
    return {
        line.split(";")[0].strip()
        for line in text.splitlines()
        if line.strip() and not line.strip().startswith("#")
    }


def option_value(args, name):
    return next((args[i + 1] for i, a in enumerate(args[:-1]) if a == name), None)


def positional_specs(args):
    takes_value = {"--python", "--target", "-r", "--requirement", "--requirements"}
    specs, skip = set(), False
    for a in args:
        if skip:
            skip = False
        elif a in takes_value:
            skip = True
        elif not a.startswith("-"):
            specs.add(a)
    return specs


def test_build_drive_installs_exactly_the_uv_exported_locked_packages_into_the_drive_lib_for_the_pis_python(tmp_path):
    record = tmp_path / "uv-calls"
    env = fake_build_env(tmp_path, record)
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    installs = [
        {
            "python": option_value(call["args"], "--python"),
            "target": option_value(call["args"], "--target"),
            "specs": positional_specs(call["args"]) | requirement_specs(call["requirements"]),
        }
        for call in uv_pip_install_calls(record)
    ]
    assert installs == [{
        "python": "/usr/bin/python3.13",
        "target": str(lib),
        "specs": requirement_specs(EXPORTED),
    }]


INSTALLED_PACKAGES = {
    "mpv.py": "import os\n",
    "PySide6/__init__.py": "",
    "PySide6/scripts/__init__.py": "",
    "PySide6/scripts/deploy_lib/__init__.py": "",
    "PySide6/scripts/deploy_lib/config.py": "x = 1\n",
}


def fake_uv_installing_packages(tmp_path, files):
    """Replace the fake uv with one whose `pip install --target <lib>` writes `files` into <lib>."""
    writes = "\n".join(
        f'mkdir -p "$target/{os.path.dirname(name)}" && printf %s {shlex.quote(body)} > "$target/{name}"'
        for name, body in files.items()
    )
    fake_command(tmp_path / "bin", "uv", f"""
if [ "$1" = export ]; then cat "{tmp_path / 'exported.txt'}"; exit 0; fi
target=; prev=
for a; do [ "$prev" = --target ] && target=$a; prev=$a; done
{writes}""")


def test_build_drive_leaves_unchecked_hash_bytecode_next_to_every_installed_module_except_under_deploy_lib(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_uv_installing_packages(tmp_path, INSTALLED_PACKAGES)
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    unchecked_hash = 0b01
    flags = {
        str(module.relative_to(lib)): int.from_bytes(pyc.read_bytes()[4:8], "little") if pyc.exists() else None
        for module in lib.rglob("*.py")
        for pyc in [Path(importlib.util.cache_from_source(str(module)))]
    }
    assert flags == {
        name: None if "deploy_lib" in Path(name).parts else unchecked_hash
        for name in INSTALLED_PACKAGES
    }


def test_build_drive_removes_a_package_left_in_the_drive_lib_by_an_earlier_build(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_uv_installing_packages(tmp_path, INSTALLED_PACKAGES)
    drive = tmp_path / "drive"
    stale = drive / "mediatagger" / "lib-linux-aarch64-cp313" / "oldpkg"
    stale.mkdir(parents=True)
    (stale / "__init__.py").write_text("")

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    assert not stale.exists()


def test_build_drive_copies_every_pi_apt_cache_deb_into_the_drive_debs_with_the_packages_index_built_there(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_command(tmp_path / "bin", "apt-ftparchive", """
[ "$1" = packages ] && [ "$2" = . ] && [ $# -eq 2 ] || exit 2
for f in *.deb; do printf 'Filename: %s/%s\\n' "$PWD" "$f"; done""")
    archives = Path(env["APTPI"]) / "var" / "cache" / "apt" / "archives"
    (archives / "mpv_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\nmpv")
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    debs = drive / "mediatagger" / "debs"
    pi_debs = sorted(archives.glob("*.deb"))
    assert {p.name: p.read_bytes() for p in debs.iterdir()} == {
        **{p.name: p.read_bytes() for p in pi_debs},
        "Packages": "".join(f"Filename: {debs}/{p.name}\n" for p in pi_debs).encode(),
    }
